10	import { BOARD_UPLOAD_DIR, type StageAction } from "./board-shared";
11	
12	const DEFAULT_COLUMNS = ["Ideas", "Backlog", "In progress", "Review", "Done"];
13	
14	// Root of the deployed repo (where scripts/ lives). The web process runs from
15	// /opt/nxeon in production; process.cwd() is the safe, correct base for the
16	// relative script paths the pipeline actions invoke.
17	const PROJECT_ROOT = process.env.NXEON_PROJECT_ROOT ?? process.cwd();
18	const STAGE_LOG_DIR = join(BOARD_UPLOAD_DIR, "stage-logs");
