74	// ---- Apps ------------------------------------------------------------------
75	
76	function slugify(name: string): string {
77	  return name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "app";
78	}
