80	/** All apps/products, oldest first, with their board counts and bound server. */
81	export async function listApps(): Promise<AppSummary[]> {
82	  await requireAdmin();
83	  const apps = await db.app.findMany({
84	    orderBy: { createdAt: "asc" },
85	    include: { _count: { select: { boards: true } }, server: { select: { id: true, name: true, status: true } } },
86	  });
87	  return apps.map((a) => ({
88	    id: a.id,
89	    name: a.name,
90	    slug: a.slug,
91	    color: a.color,
92	    boardCount: a._count.boards,
93	    serverId: a.server?.id ?? null,
94	    serverName: a.server?.name ?? null,
95	    serverStatus: a.server?.status ?? null,
96	    codePath: a.codePath,
97	    repoUrl: a.repoUrl,
98	    context: a.context,
99	  }));
100	}
