102	/** Admin-gated list of real servers an app can be bound to (for the board's
103	 *  server picker). Newest first, capped — enough to choose from without loading
104	 *  the whole fleet. */
105	export async function listServersForBinding(): Promise<ServerOption[]> {
106	  await requireAdmin();
107	  const servers = await db.server.findMany({
108	    orderBy: { createdAt: "desc" },
109	    select: { id: true, name: true, ipAddress: true, status: true },
110	    take: 500,
111	  });
112	  return servers.map((s) => ({ id: s.id, name: s.name, ipAddress: s.ipAddress, status: s.status }));
113	}
