115	/** Bind an app to a real Server (or unbind with serverId=null). Admin-gated. */
116	export async function setAppServer(appId: string, serverId: string | null): Promise<{ error?: string }> {
117	  await requireAdmin();
118	  if (serverId) {
119	    const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true } });
120	    if (!server) return { error: "Server not found." };
121	  }
122	  await db.app.update({ where: { id: appId }, data: { serverId: serverId || null } }).catch(() => undefined);
123	  revalidatePath("/admin/board");
124	  return {};
125	}
