127	/**
128	 * Update an app's working-context metadata: where its code lives (`codePath`),
129	 * its git remote (`repoUrl`), a free-form markdown `context` (stack / build /
130	 * deploy / gotchas), and optionally its display `color`. Admin-gated. Only the
131	 * keys present in `patch` are written, so callers can save one field without
132	 * touching the others; an empty string clears a field to null.
133	 */
134	export async function updateAppMeta(
135	  appId: string,
136	  patch: { codePath?: string; repoUrl?: string; context?: string; color?: string },
137	): Promise<{ error?: string }> {
138	  await requireAdmin();
139	  const app = await db.app.findUnique({ where: { id: appId }, select: { id: true } });
140	  if (!app) return { error: "App not found." };
141	  const data: Record<string, string | null> = {};
142	  if (patch.codePath !== undefined) data.codePath = patch.codePath.trim().slice(0, 500) || null;
143	  if (patch.repoUrl !== undefined) data.repoUrl = patch.repoUrl.trim().slice(0, 500) || null;
144	  if (patch.context !== undefined) data.context = patch.context.slice(0, 20_000) || null;
145	  if (patch.color !== undefined) data.color = patch.color.trim().slice(0, 32) || null;
146	  if (Object.keys(data).length === 0) return {};
147	  await db.app.update({ where: { id: appId }, data }).catch(() => undefined);
148	  revalidatePath("/admin/board");
149	  return {};
150	}
