152	export async function createApp(name: string, color?: string | null): Promise<{ id?: string; error?: string }> {
153	  await requireAdmin();
154	  const clean = String(name ?? "").trim().slice(0, 60);
155	  if (!clean) return { error: "Enter an app name." };
156	  // Ensure a unique slug even when two apps share a base name.
157	  let slug = slugify(clean);
158	  for (let n = 2; await db.app.findUnique({ where: { slug } }); n++) slug = `${slugify(clean)}-${n}`;
159	  const app = await db.app.create({ data: { name: clean, slug, color: color?.trim() || null } });
160	  revalidatePath("/admin/board");
161	  return { id: app.id };
162	}
