186	export async function createBoard(name: string, appId?: string | null): Promise<{ id?: string; error?: string }> {
187	  await requireAdmin();
188	  const clean = String(name ?? "").trim().slice(0, 60);
189	  if (!clean) return { error: "Enter a board name." };
190	  const id = await createBoardInternal(clean, appId ?? null);
191	  revalidatePath("/admin/board");
192	  return { id };
193	}
