209	/** Full board with columns + card summaries (non-archived). */
210	export async function getBoard(boardId: string): Promise<BoardData | null> {
211	  await requireAdmin();
212	  const board = await db.board.findUnique({
213	    where: { id: boardId },
214	    include: {
215	      columns: {
216	        orderBy: { position: "asc" },
217	        include: {
218	          cards: {
219	            where: { archivedAt: null },
220	            orderBy: { position: "asc" },
221	            include: { _count: { select: { attachments: true, comments: true } } },
222	          },
223	        },
224	      },
225	    },
226	  });
227	  if (!board) return null;
228	  return {
229	    id: board.id,
230	    name: board.name,
231	    columns: board.columns.map((c) => ({
232	      id: c.id,
233	      name: c.name,
234	      position: c.position,
235	      cards: c.cards.map((card) => ({
236	        id: card.id,
237	        title: card.title,
238	        type: card.type,
239	        priority: card.priority,
240	        labels: card.labels,
241	        assignee: card.assignee,
242	        attachmentCount: card._count.attachments,
243	        commentCount: card._count.comments,
244	        hasDescription: card.description.trim().length > 0,
245	        updatedAt: card.updatedAt.toISOString(),
246	      })),
247	    })),
248	  };
249	}
