269	export async function deleteColumn(id: string): Promise<{ error?: string }> {
270	  await requireAdmin();
271	  const cards = await db.card.count({ where: { columnId: id, archivedAt: null } });
272	  if (cards > 0) return { error: "Move or archive its cards first." };
273	  await db.boardColumn.delete({ where: { id } }).catch(() => undefined);
274	  revalidatePath("/admin/board");
275	  return {};
276	}
