278	/** Reorder a column within its board; renumber siblings. */
279	export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
280	  await requireAdmin();
281	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
282	  if (!col) return;
283	  const siblings = await db.boardColumn.findMany({
284	    where: { boardId: col.boardId, NOT: { id: columnId } },
285	    orderBy: { position: "asc" },
286	    select: { id: true },
287	  });
288	  const order = siblings.map((s) => s.id);
289	  const idx = Math.max(0, Math.min(toIndex, order.length));
290	  order.splice(idx, 0, columnId);
291	  await db.$transaction(order.map((id, i) => db.boardColumn.update({ where: { id }, data: { position: i } })));
292	  revalidatePath("/admin/board");
293	}
