361	// ---- Cards -----------------------------------------------------------------
362	
363	const TYPES = ["IDEA", "FEATURE", "BUG", "CHORE"];
364	const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];
365	
366	export async function createCard(columnId: string, title: string, type = "FEATURE"): Promise<{ id?: string; error?: string }> {
367	  await requireAdmin();
368	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
369	  if (!col) return { error: "Column not found." };
370	  const clean = String(title ?? "").trim().slice(0, 200);
371	  if (!clean) return { error: "Enter a title." };
372	  const max = await db.card.aggregate({ where: { columnId }, _max: { position: true } });
373	  const card = await db.card.create({
374	    data: { boardId: col.boardId, columnId, title: clean, type: (TYPES.includes(type) ? type : "FEATURE") as never, position: (max._max.position ?? -1) + 1 },
375	  });
376	  revalidatePath("/admin/board");
377	  return { id: card.id };
378	}
379	
380	export async function updateCard(
381	  id: string,
382	  patch: { title?: string; description?: string; type?: string; priority?: string; labels?: string[]; assignee?: string | null },
383	): Promise<{ error?: string }> {
384	  await requireAdmin();
385	  const data: Record<string, unknown> = {};
386	  if (patch.title !== undefined) { const t = patch.title.trim().slice(0, 200); if (!t) return { error: "Title can’t be empty." }; data.title = t; }
387	  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
388	  if (patch.type !== undefined && TYPES.includes(patch.type)) data.type = patch.type;
389	  if (patch.priority !== undefined && PRIORITIES.includes(patch.priority)) data.priority = patch.priority;
390	  if (patch.labels !== undefined) data.labels = patch.labels.map((l) => l.trim().slice(0, 24)).filter(Boolean).slice(0, 8);
391	  if (patch.assignee !== undefined) data.assignee = patch.assignee?.trim().slice(0, 40) || null;
392	  await db.card.update({ where: { id }, data });
393	  revalidatePath("/admin/board");
394	  return {};
395	}
