397	/** Move a card to a column at a position; renumber siblings. */
398	export async function moveCard(cardId: string, toColumnId: string, toIndex: number): Promise<void> {
399	  await requireAdmin();
400	  const card = await db.card.findUnique({ where: { id: cardId }, select: { columnId: true, boardId: true } });
401	  const col = await db.boardColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
402	  if (!card || !col || col.boardId !== card.boardId) return;
403	  const siblings = await db.card.findMany({ where: { columnId: toColumnId, archivedAt: null, NOT: { id: cardId } }, orderBy: { position: "asc" }, select: { id: true } });
404	  const order = siblings.map((s) => s.id);
405	  const idx = Math.max(0, Math.min(toIndex, order.length));
406	  order.splice(idx, 0, cardId);
407	  await db.$transaction([
408	    db.card.update({ where: { id: cardId }, data: { columnId: toColumnId } }),
409	    ...order.map((id, i) => db.card.update({ where: { id }, data: { position: i } })),
410	  ]);
411	  revalidatePath("/admin/board");
412	}
