470	// ---- Execution pipeline ----------------------------------------------------
471	// Moving a card through stages can trigger real work: rendering docs, deploying
472	// to staging, promoting to production, or committing to GitHub. These are NEVER
473	// fired automatically by moveCard — they are only run when a human clicks the
474	// explicit, confirm-gated button in the card modal (see runCardStageAction).
475	// Each run is spawned DETACHED with output captured to a log file; a start
476	// comment is posted immediately and a completion comment (with the log tail) is
477	// posted when the child exits, so the request thread never blocks on a long
478	// deploy.
479	
480	// Fixed command table — actions are chosen from this allowlist only; no user
481	// input is ever interpolated into a shell command. The GitHub commit message is
482	// passed via an environment variable and expanded inside double quotes, so its
483	// contents can't break out into further shell parsing.
484	const STAGE_ACTIONS: Record<StageAction, { label: string; cmd: string; args: string[] }> = {
485	  docs: { label: "Publish to docs", cmd: "node", args: ["scripts/publish-docs.mjs"] },
486	  staging: { label: "Deploy to staging", cmd: "bash", args: ["scripts/deploy-staging.sh"] },
487	  production: { label: "Promote to production", cmd: "bash", args: ["scripts/promote-production.sh"] },
488	  github: { label: "Commit to GitHub", cmd: "bash", args: ["-c", 'git add -A && git commit -m "$NXEON_COMMIT_MSG"'] },
489	};
490	
491	async function readLogTail(logPath: string, max = 4000): Promise<string> {
492	  try {
493	    const buf = await fs.readFile(logPath, "utf8");
494	    return buf.length > max ? "…" + buf.slice(-max) : buf || "(no output)";
495	  } catch {
496	    return "(log unavailable)";
497	  }
498	}
499	
500	/**
501	 * Run a pipeline action for a card. Admin-gated. Spawns the mapped script
502	 * detached with output captured to a per-run log, records a start comment, and
503	 * (when the child exits) a completion comment with the log tail. Returns as soon
504	 * as the child is launched — it never waits for a long deploy to finish.
505	 */
506	export async function runCardStageAction(
507	  cardId: string,
508	  action: StageAction,
509	): Promise<{ error?: string; started?: boolean; logPath?: string }> {
510	  const admin = await requireAdmin();
511	  const spec = STAGE_ACTIONS[action];
512	  if (!spec) return { error: "Unknown action." };
513	  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true, title: true } });
514	  if (!card) return { error: "Card not found." };
515	
516	  await fs.mkdir(STAGE_LOG_DIR, { recursive: true });
517	  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
518	  const logPath = join(STAGE_LOG_DIR, `${cardId}-${action}-${stamp}.log`);
519	
520	  const env: NodeJS.ProcessEnv = { ...process.env };
521	  if (action === "github") {
522	    env.NXEON_COMMIT_MSG = `board: ${card.title} (card ${cardId})`.replace(/\s+/g, " ").slice(0, 180);
523	  }
524	
525	  const author = admin.email.split("@")[0];
526	  await db.cardComment.create({
527	    data: { cardId, authorName: author, body: `▶️ Started **${spec.label}**.\nLog: \`${logPath}\`` },
528	  });
529	
530	  let logFd;
531	  try {
532	    logFd = await fs.open(logPath, "a");
533	  } catch (e) {
534	    return { error: `Could not open log file: ${(e as Error).message}` };
535	  }
536	
537	  try {
538	    const child = spawn(spec.cmd, spec.args, {
539	      cwd: PROJECT_ROOT,
540	      env,
541	      detached: true,
542	      stdio: ["ignore", logFd.fd, logFd.fd],
543	    });
544	    child.unref();
545	    child.on("error", (err) => {
546	      logFd.close().catch(() => undefined);
547	      db.cardComment
548	        .create({ data: { cardId, authorName: "system", body: `❌ **${spec.label}** failed to start: ${err.message}` } })
549	        .catch(() => undefined);
550	    });
551	    child.on("exit", async (code, signal) => {
552	      await logFd.close().catch(() => undefined);
553	      const tail = await readLogTail(logPath);
554	      const status = code === 0 ? "✅ succeeded" : `❌ exited with ${code ?? `signal ${signal}`}`;
555	      await db.cardComment
556	        .create({ data: { cardId, authorName: "system", body: `**${spec.label}** ${status}\n\n\`\`\`\n${tail}\n\`\`\`` } })
557	        .catch(() => undefined);
558	    });
559	  } catch (e) {
560	    await logFd.close().catch(() => undefined);
561	    return { error: `Failed to launch: ${(e as Error).message}` };
562	  }
563	
564	  revalidatePath("/admin/board");
565	  return { started: true, logPath };
566	}
