48	/**
49	 * Operator outcome control (mark interested / not-interested / meeting-booked /
50	 * closed / reopen). Advances the linked contact's pipeline stage to match so the
51	 * inbox and the pipeline never disagree.
52	 */
53	export type ConversationOutcome =
54	  | "INTERESTED"
55	  | "NOT_INTERESTED"
56	  | "MEETING_BOOKED"
57	  | "CLOSED"
58	  | "REOPEN";
59	
60	export async function setConversationOutcome(conversationId: string, outcome: ConversationOutcome): Promise<ActionState> {
61	  await requireArea("platform");
62	  const convo = await db.conversation.findUnique({ where: { id: conversationId }, select: { contactId: true } });
63	  if (!convo) return { error: "Conversation not found." };
64	
65	  // (conversation status, category, contact stage) for each outcome.
66	  const map: Record<
67	    ConversationOutcome,
68	    { status: "INTERESTED" | "NOT_INTERESTED" | "CLOSED" | "OPEN"; category: string; stage?: "INTERESTED" | "MEETING_BOOKED" | "LOST" }
69	  > = {
70	    INTERESTED: { status: "INTERESTED", category: "INTERESTED", stage: "INTERESTED" },
71	    NOT_INTERESTED: { status: "NOT_INTERESTED", category: "NOT_INTERESTED", stage: "LOST" },
72	    MEETING_BOOKED: { status: "INTERESTED", category: "MEETING_BOOKED", stage: "MEETING_BOOKED" },
73	    CLOSED: { status: "CLOSED", category: "" },
74	    REOPEN: { status: "OPEN", category: "" },
75	  };
76	  const m = map[outcome];
77	
78	  await db.conversation.update({ where: { id: conversationId }, data: { status: m.status, category: m.category, unread: false } });
79	  if (m.stage) {
80	    await db.contact.update({ where: { id: convo.contactId }, data: { stage: m.stage } }).catch(() => null);
81	  }
82	  await logEvent("info", "coldemail.conversation.outcome", { conversationId, outcome });
83	  revalidatePath(INBOX_PATH);
84	  return { ok: true };
85	}
