91	    const { coldEmailInboxPoll } = await import("@/worker/coldemail-inbox");
92	    await coldEmailInboxPoll();
93	  } catch (err) {
94	    await logEvent("error", "coldemail.inbox.manualPoll", { message: String((err as Error)?.message ?? err) });
95	    return { error: "Could not poll inboxes (are IMAP credentials configured?)." };
96	  }
97	  revalidatePath(INBOX_PATH);
