7	  isImprovementStatus,
8	  type ImprovementStatus,
9	  type BulkImprovementSelector,
10	} from "@/lib/improvement-status";
11	
12	/**
13	 * Owner-facing approve/decline actions for the Improvements board
14	 * (app/admin/improvements). Every action is ADMIN-guarded via requireAdmin().
15	 * NOTE: a "use server" module may ONLY export async functions — the status
16	 * constants and types live in lib/improvement-status.ts.
17	 */
18	
19	function assertStatus(status: string): asserts status is ImprovementStatus {
20	  if (!isImprovementStatus(status)) {
21	    throw new Error(`Invalid improvement status: ${status}`);
22	  }
23	}
24	
25	async function audit(userId: string | null, action: string, detail?: string) {
26	  try {
27	    await db.auditLog.create({ data: { userId, action, detail } });
28	  } catch {
29	    /* auditing is best-effort — never block the status change on it */
30	  }
31	}
32	
33	/** Set a single improvement's status. */
34	export async function setImprovementStatus(id: string, status: string): Promise<void> {
35	  const admin = await requireAdmin();
36	  assertStatus(status);
37	  await db.improvement.update({ where: { id }, data: { status } });
38	  await audit(admin.id, "improvement.status", `${id} → ${status}`);
39	  revalidatePath("/admin/improvements");
40	}
41	
42	/** Set (or clear) a single improvement's owner note. */
43	export async function setImprovementNote(id: string, note: string): Promise<void> {
44	  const admin = await requireAdmin();
45	  const trimmed = note.trim().slice(0, 4000);
46	  await db.improvement.update({
47	    where: { id },
48	    data: { ownerNote: trimmed.length > 0 ? trimmed : null },
49	  });
50	  await audit(admin.id, "improvement.note", `${id} (${trimmed.length} chars)`);
51	  revalidatePath("/admin/improvements");
52	}
53	
54	/**
55	 * Bulk status change. Accepts either an explicit id list, a filter (category /
56	 * current status), or both. With no constraints at all it is a no-op guard —
57	 * we refuse an unbounded update so "Approve all" can never sweep the whole
58	 * table by accident.
59	 */
60	export async function bulkSetStatus(
61	  selector: BulkImprovementSelector,
62	  status: string
63	): Promise<{ count: number }> {
64	  const admin = await requireAdmin();
65	  assertStatus(status);
66	
67	  const where: {
68	    id?: { in: string[] };
69	    category?: string;
70	    status?: string;
71	  } = {};
72	  if (selector.ids && selector.ids.length > 0) where.id = { in: selector.ids };
73	  if (selector.category) where.category = selector.category;
74	  if (selector.onlyStatus) {
75	    assertStatus(selector.onlyStatus);
76	    where.status = selector.onlyStatus;
77	  }
78	
79	  // Refuse a truly unconstrained bulk update.
80	  if (Object.keys(where).length === 0) return { count: 0 };
81	
82	  const res = await db.improvement.updateMany({ where, data: { status } });
83	  await audit(
84	    admin.id,
85	    "improvement.bulkStatus",
86	    `${res.count} row(s) → ${status} (${JSON.stringify(selector)})`
87	  );
88	  revalidatePath("/admin/improvements");
89	  return { count: res.count };
90	}
