754	/** Minutes-from-midnight for an "HH:MM" string, or null if blank/invalid. */
755	function parseHhmm(v: string): number | null {
756	  const m = /^(\d{1,2}):(\d{2})$/.exec(v.trim());
757	  if (!m) return null;
758	  const h = Number(m[1]);
759	  const min = Number(m[2]);
760	  if (h > 23 || min > 59) return null;
761	  return h * 60 + min;
762	}
