767	  const campaignId = String(formData.get("campaignId") ?? "").trim();
768	  if (!campaignId) return { error: "Missing campaign." };
769	  const startRaw = String(formData.get("sendWindowStart") ?? "").trim();
770	  const endRaw = String(formData.get("sendWindowEnd") ?? "").trim();
771	  const timezone = String(formData.get("timezone") ?? "UTC").trim().slice(0, 64) || "UTC";
772	
773	  const sendWindowStart = startRaw ? parseHhmm(startRaw) : null;
774	  const sendWindowEnd = endRaw ? parseHhmm(endRaw) : null;
775	  if ((startRaw && sendWindowStart === null) || (endRaw && sendWindowEnd === null)) {
776	    return { error: "Send window times must be HH:MM (24-hour)." };
777	  }
778	  // Both or neither — a one-sided window is ambiguous.
779	  if ((sendWindowStart === null) !== (sendWindowEnd === null)) {
780	    return { error: "Set both a start and an end time, or leave both blank." };
781	  }
782	
783	  await db.coldCampaign.update({
784	    where: { id: campaignId },
785	    data: { sendWindowStart, sendWindowEnd, timezone },
786	  });
787	  revalidatePath(`/admin/coldemail/campaigns/${campaignId}`);
788	  return { ok: true };
