68	  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
69	  // to refund it all over again.
70	  const invoiceId = String(formData.get("invoiceId") ?? "").trim();
71	
72	  if (!userId) return { error: "Missing customer." };
73	  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };
74	
75	  const user = await db.user.findUnique({ where: { id: userId } });
76	  if (!user) return { error: "Customer not found." };
77	
78	  // Resolve and validate the target invoice when one was supplied.
79	  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
80	  // How much of the invoice was already refunded WHEN WE READ IT. Two jobs: it is
81	  // the compare-and-swap anchor for the write below, and it is what makes the
82	  // Stripe idempotency key describe a STEP of the refund rather than an amount.
83	  let alreadyRefunded = 0;
84	  if (invoiceId) {
85	    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
86	    if (!invoice) return { error: "Invoice not found." };
87	    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
88	    alreadyRefunded = invoice.refundedCents ?? 0;
89	    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
90	    if (refundable === 0) {
91	      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
92	    }
93	    if (cents > refundable) {
94	      return {
95	        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
96	      };
97	    }
98	  }
99	
100	  // --- Route the refund back to the ORIGINAL card for this charge ---
101	  let method: "stripe" | "wallet" = "wallet";
102	  let stripeRefundId: string | null = null;
103	  if (stripeConfigured()) {
104	    // Prefer the charge that actually paid THIS invoice; only fall back to the
105	    // latest top-up when no invoice was specified (the standalone refund form).
106	    const tx = await db.walletTransaction.findFirst({
107	      where: invoice
108	        ? {
109	            userId,
110	            description: { contains: "Stripe payment (cs_" },
111	            createdAt: { lte: invoice.paidAt ?? invoice.createdAt },
112	          }
113	        : { userId, description: { contains: "Stripe payment (cs_" } },
114	      orderBy: { createdAt: "desc" },
115	    });
116	    const sessionId = sessionIdFrom(tx?.description);
117	    if (sessionId) {
118	      try {
119	        const session = await stripe().checkout.sessions.retrieve(sessionId);
120	        const pi =
121	          typeof session.payment_intent === "string"
122	            ? session.payment_intent
123	            : session.payment_intent?.id;
124	        if (pi) {
125	          // Idempotency key derived from the target, the amount AND how much of
126	          // this invoice had already been refunded when this request read it.
127	          //
128	          // The first two alone (`refund:<target>:<pi>:<cents>`) deduplicated two
129	          // submits — which is the point — but they ALSO deduplicated two genuinely
130	          // different refunds that happened to be the same size. Two $10 partial
131	          // refunds against a $100 invoice are a completely ordinary support
132	          // sequence, and Stripe replayed the first refund for the second: ONE $10
133	          // refund reached the card while this action debited the customer's wallet
134	          // $10 twice and recorded $20 against the invoice. The customer was $10
135	          // down, and the two systems agreed with each other about it.
136	          //
137	          // `alreadyRefunded` is 0 then 10 across those two calls, so they are
138	          // distinct requests; a true double-submit reads the same value and still
139	          // collapses to one refund. (Standalone refunds with no invoice keep the
140	          // old shape — there is no per-target running total to anchor to.)
141	          const refund = await stripe().refunds.create(
142	            { payment_intent: pi, amount: cents },
143	            {
144	              idempotencyKey: invoiceId
145	                ? `refund:${invoiceId}:${pi}:${alreadyRefunded}:${cents}`
146	                : `refund:${userId}:${pi}:${cents}`,
147	            }
148	          );
149	          stripeRefundId = refund.id;
150	          method = "stripe";
151	        }
152	      } catch {
153	        // Stripe refund failed / not refundable — fall back to wallet-only.
154	        method = "wallet";
155	      }
156	    }
157	  }
158	
159	  const available = Math.max(0, user.balanceCents);
160	  const walletDebit = Math.min(cents, available);
161	  if (method === "wallet" && walletDebit < cents) {
162	    return {
163	      error:
164	        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
165	    };
166	  }
167	
168	  const writeOff = cents - walletDebit; // real cash returned that the wallet couldn't cover
169	  const noteBits = [
170	    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
171	    invoice ? `invoice ${invoice.number ?? invoice.id}` : null,
172	    reason,
173	  ].filter(Boolean);
174	  const description = `Refund — ${noteBits.join(" · ")}`;
175	
176	  try {
177	    await db.$transaction(async (tx) => {
178	      // COMPARE-AND-SWAP on the invoice's running refunded total, and it goes FIRST
179	      // so that losing it writes nothing at all.
180	      //
181	      // Two admins (or one admin in two tabs) both read `refundedCents: 0`, both send
182	      // the same $10 refund, and Stripe — correctly — returns ONE refund for the two
183	      // identical idempotency keys. Without this guard both requests then ran the
184	      // block below: two wallet debits and two ledger rows for one real refund, while
185	      // `refundedCents` ended at 10 because each computed it from the same stale read.
186	      // History, balance and the card all disagreed. Only the update that still sees
187	      // the value it read may proceed.
188	      if (invoice) {
189	        const total = alreadyRefunded + cents;
190	        const advanced = await tx.invoice.updateMany({
191	          where: { id: invoice.id, refundedCents: alreadyRefunded },
192	          data: {
193	            refundedCents: total,
194	            ...(total >= invoice.amountCents ? { status: "REFUNDED" as const } : {}),
195	          },
196	        });
197	        if (advanced.count === 0) throw new AlreadyRefundedError();
198	      }
199	      if (walletDebit > 0) {
200	        await tx.user.update({
201	          where: { id: userId },
202	          data: { balanceCents: { decrement: walletDebit } },
203	        });
204	      }
205	      // The ledger row must equal the ACTUAL balance change. It used to record the
206	      // full refund (-cents) while the balance only fell by what was available, so a
207	      // $50 card refund against a $5 wallet left history and balance disagreeing by
208	      // $45 permanently. The uncovered remainder is a real-cash write-off and gets
209	      // its own zero-balance-effect line, so the story is legible without lying
210	      // about the arithmetic.
211	      if (walletDebit > 0) {
212	        await tx.walletTransaction.create({
213	          data: { userId, amountCents: -walletDebit, description },
214	        });
215	      }
216	      if (writeOff > 0) {
217	        await tx.walletTransaction.create({
218	          data: {
219	            userId,
220	            amountCents: 0,
221	            description:
222	              `Write-off — $${(writeOff / 100).toFixed(2)} of this refund was returned to the card ` +
223	              `beyond the wallet balance, so no wallet deduction applies to that portion. ` +
224	              noteBits.join(" · "),
225	          },
226	        });
227	      }
228	    });
229	  } catch (e) {
230	    if (e instanceof AlreadyRefundedError) {
231	      return {
232	        error:
233	          "This invoice was refunded by another request a moment ago — reload to see the current " +
234	          "refunded total before issuing another. Nothing was charged or debited twice.",
235	      };
236	    }
237	    throw e;
238	  }
239	
240	  await audit(
241	    admin.id,
242	    "billing.refund",
243	    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
244	      stripeRefundId ? ` (${stripeRefundId})` : ""
245	    }`
246	  );
247	  revalidatePath("/admin/billing");
248	  revalidatePath(`/admin/users/${userId}`);
249	  revalidatePath("/dashboard/billing");
250	
251	  const dollars = `$${(cents / 100).toFixed(2)}`;
252	  return {
253	    message:
254	      method === "stripe"
255	        ? `Refunded ${dollars} to the customer's card (Stripe ${stripeRefundId}).`
256	        : `Refunded ${dollars} to the wallet balance.`,
257	  };
258	}
