300	/**
301	 * Bulk-void a set of open/unpaid invoices. Paid invoices are skipped (they must
302	 * be refunded instead) and already-void ones are ignored. Returns counts.
303	 */
304	export async function bulkVoidInvoices(
305	  ids: string[]
306	): Promise<{ voided: number; skipped: number }> {
307	  const admin = await requireArea("billing");
308	  const unique = [...new Set((ids ?? []).filter(Boolean))].slice(0, 500);
309	  if (unique.length === 0) return { voided: 0, skipped: 0 };
310	
311	  const invoices = await db.invoice.findMany({ where: { id: { in: unique } } });
312	  const voidable = invoices.filter((i) => i.status === "OPEN" || i.status === "REFUNDED");
313	
314	  if (voidable.length > 0) {
315	    await db.invoice.updateMany({
316	      where: { id: { in: voidable.map((i) => i.id) } },
317	      data: { status: "VOID", paidAt: null },
318	    });
319	  }
320	
321	  await audit(admin.id, "billing.bulk_void", `${voidable.length} voided of ${unique.length}`);
322	  revalidatePath("/admin/invoices");
323	  revalidatePath("/dashboard/invoices");
324	  return { voided: voidable.length, skipped: unique.length - voidable.length };
325	}
