179	/**
180	 * Paste-a-CSV import. Columns (any order): business/name, vertical, email, url/website, notes.
181	 * Server-side parse, no enrichment, no scraping. Returns a summary in the channel.
182	 */
183	export async function importProspectsCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
184	  await requireArea("platform");
185	  const csv = String(formData.get("csv") ?? "");
186	  if (!csv.trim()) return { error: "Paste some CSV rows first." };
187	
188	  const { headers, rows } = parseCsv(csv);
189	  if (headers.length === 0 || rows.length === 0) {
190	    return { error: "Could not find a header row and at least one data row." };
191	  }
192	  const alias: Record<string, string> = {
193	    business: "businessName",
194	    businessname: "businessName",
195	    name: "businessName",
196	    company: "businessName",
197	    vertical: "vertical",
198	    category: "vertical",
199	    type: "vertical",
200	    email: "contactEmail",
201	    contactemail: "contactEmail",
202	    url: "currentSiteUrl",
203	    website: "currentSiteUrl",
204	    site: "currentSiteUrl",
205	    notes: "notes",
206	    note: "notes",
207	  };
208	  const cols = headers.map((h) => alias[h] ?? "");
209	  if (!cols.includes("businessName")) {
210	    return { error: "CSV needs at least a 'business' (name) column." };
211	  }
212	
213	  let created = 0;
214	  let skipped = 0;
215	  for (const r of rows) {
216	    const rec: Record<string, string> = {};
217	    cols.forEach((field, i) => {
218	      if (field) rec[field] = (r[i] ?? "").trim();
219	    });
220	    const businessName = (rec.businessName ?? "").trim();
221	    if (!businessName) {
222	      skipped++;
223	      continue;
224	    }
225	    const email = (rec.contactEmail ?? "").trim();
226	    try {
227	      await db.agencyProspect.create({
228	        data: {
229	          businessName: businessName.slice(0, 160),
230	          vertical: rec.vertical ? slugify(rec.vertical) : "",
231	          contactEmail: email && emailCheck.safeParse(email).success ? email : null,
232	          currentSiteUrl: (rec.currentSiteUrl ?? "").slice(0, 300) || null,
233	          notes: (rec.notes ?? "").slice(0, 2000),
234	        },
235	      });
236	      created++;
237	    } catch {
238	      skipped++;
239	    }
240	  }
241	  revalidatePath("/admin/agency/prospects");
242	  revalidatePath("/admin/agency");
243	  return { ok: true, error: `Imported ${created} prospect${created === 1 ? "" : "s"}${skipped ? `, skipped ${skipped}` : ""}.` };
244	}
