375	/**
376	 * OPERATOR-TRIGGERED scrape of the prospect's currentSiteUrl, then generate a
377	 * demo from what was extracted. The scrape is SSRF-safe (lib/agency/scrape.ts):
378	 * https/http only, private/reserved IPs refused, per-hop redirect re-validation,
379	 * size + time caps. On any refusal/failure the scrape result is still recorded and
380	 * generation proceeds from whatever stored text exists (graceful degrade).
381	 */
382	export async function scrapeAndGenerate(prospectId: string): Promise<ActionState> {
383	  await requireArea("platform");
384	  const prospect = await db.agencyProspect.findUnique({ where: { id: prospectId } });
385	  if (!prospect) return { error: "Prospect not found." };
386	  if (!prospect.currentSiteUrl) {
387	    return { error: "This prospect has no current site URL to scrape." };
388	  }
389	
390	  const result = await scrapeSite(prospect.currentSiteUrl);
391	  const status = result.ok ? "ok" : `refused: ${result.error}`.slice(0, 200);
392	  try {
393	    await db.agencyProspect.update({
394	      where: { id: prospect.id },
395	      data: {
396	        scrapeJson: result as unknown as Prisma.InputJsonValue,
397	        scrapeStatus: status,
398	        scrapedAt: new Date(),
399	      },
400	    });
401	    await db.agencyActivity.create({
402	      data: {
403	        prospectId: prospect.id,
404	        kind: "SCRAPE",
405	        body: result.ok
406	          ? `Scraped ${result.finalUrl || prospect.currentSiteUrl} (${result.bytes} bytes).`
407	          : `Scrape refused/failed: ${result.error}`,
408	        meta: { ok: result.ok, status: result.status, finalUrl: result.finalUrl } as Prisma.InputJsonValue,
409	      },
410	    });
411	  } catch (err) {
412	    await logEvent("error", "agency.scrape.persist", { message: String(err), prospectId });
413	  }
414	  await logEvent("info", "agency.scrape", { prospectId, ok: result.ok, host: prospect.currentSiteUrl });
415	
416	  const pasted = result.ok
417	    ? [prospect.pastedSiteText, extractionToPastedText(result.extraction)].filter(Boolean).join("\n\n")
418	    : prospect.pastedSiteText;
419	
420	  const gen = await generateDemoForProspect(prospect, {
421	    extraction: result.ok ? result.extraction : undefined,
422	    pastedTextOverride: pasted,
423	  });
424	  if (gen.error) return gen;
425	  return {
426	    ok: true,
427	    error: result.ok
428	      ? undefined
429	      : `Demo generated, but the scrape was skipped (${result.error}).`,
430	  };
431	}
