433	/**
434	 * Deploy a demo to its subdomain. GATED. Builds the static bundle (pure), then:
435	 *  - default (Setting agency_deploy_enabled off): records DEPLOYED_STUB with the
436	 *    intended host + bundle size. NOTHING is provisioned;
437	 *  - enabled: enqueues a REAL deploy (status DEPLOYING, mode "real"). No live
438	 *    infra is touched by this build — it records intent for a future provisioner.
439	 */
440	export async function deployDemo(demoId: string): Promise<ActionState> {
441	  await requireArea("platform");
442	  const demo = await db.agencyDemoSite.findUnique({
443	    where: { id: demoId },
444	    select: { id: true, slug: true, renderedHtml: true, prospectId: true },
445	  });
446	  if (!demo) return { error: "Demo not found." };
447	
448	  const bundle = buildDeployBundle({ slug: demo.slug, renderedHtml: demo.renderedHtml });
449	  const enabled = await getSettingBool("agency_deploy_enabled");
450	
451	  try {
452	    if (enabled) {
453	      await db.agencyDemoSite.update({
454	        where: { id: demo.id },
455	        data: {
456	          status: "DEPLOYING",
457	          deployMode: "real",
458	          intendedHost: bundle.intendedHost,
459	          bundleBytes: bundle.bytes,
460	          deployedAt: new Date(),
461	        },
462	      });
463	      await db.agencyActivity.create({
464	        data: {
465	          prospectId: demo.prospectId,
