576	/**
577	 * Move a prospect to a new pipeline stage. Rejects illegal jumps (canTransition),
578	 * records a STAGE_CHANGE activity, and — on WON — ensures an AgencyClient exists.
579	 */
580	export async function moveProspectStage(prospectId: string, toStage: string): Promise<ActionState> {
581	  await requireArea("platform");
582	  if (!isDealStage(toStage)) return { error: "Invalid stage." };
583	  const prospect = await db.agencyProspect.findUnique({
584	    where: { id: prospectId },
585	    include: { client: { select: { id: true } } },
586	  });
587	  if (!prospect) return { error: "Prospect not found." };
588	
589	  const from = prospect.stage as DealStage;
590	  const to = toStage as DealStage;
591	  if (from === to) return { ok: true };
592	  if (!canTransition(from, to)) {
593	    return { error: `Cannot move ${from} → ${to} in one step.` };
594	  }
595	
596	  try {
597	    await db.agencyProspect.update({ where: { id: prospectId }, data: { stage: to } });
598	    await db.agencyActivity.create({
599	      data: {
600	        prospectId,
601	        kind: "STAGE_CHANGE",
602	        body: `Stage ${from} → ${to}.`,
603	        meta: { from, to } as Prisma.InputJsonValue,
604	      },
605	    });
606	    if (to === "WON" && !prospect.client) {
607	      await createClientForProspect(prospect.id, prospect.businessName, prospect.contactEmail);
608	    }
609	  } catch (err) {
610	    await logEvent("error", "agency.stage.move", { message: String(err), prospectId });
611	    return { error: "Could not update the stage." };
612	  }
613	
614	  revalidatePath("/admin/agency/pipeline");
615	  revalidatePath(`/admin/agency/prospects/${prospectId}`);
616	  revalidatePath("/admin/agency");
617	  return { ok: true };
618	}
