370	  if (!rule) return { error: "That rule no longer exists." };
371	
372	  const when = (rule.whenJson ?? {}) as { lookbackDays?: number };
373	  const lookbackDays = Math.max(1, Math.round(Number(when.lookbackDays) || 7));
374	  const since = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);
375	
376	  const insights = await db.adsInsight.findMany({
377	    where: {
378	      scope: "CAMPAIGN",
379	      date: { gte: since },
380	      campaign: { accountId: rule.accountId },
381	    },
382	    select: { impressions: true, clicks: true, spendCents: true, conversions: true },
383	  });
384	
385	  const rows: InsightCounters[] = insights.map((r) => ({
386	    impressions: r.impressions,
387	    clicks: r.clicks,
388	    spendCents: r.spendCents,
389	    conversions: r.conversions,
390	  }));
391	
392	  const result = evaluateRule(rule.whenJson, rule.thenJson, rows);
393	
394	  await db.adsRuleRun.create({ data: { ruleId: rule.id, matched: result.matched, note: result.note } });
