22	export async function resolveAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
23	  const admin = await requireArea("fleet");
24	  await db.abuseAlert.update({ where: { id }, data: { status: "RESOLVED", resolvedAt: new Date() } });
25	  // Closing an abuse case clears it from the queue — an attributable action.
26	  await db.auditLog.create({ data: { userId: admin.id, action: "abuse.resolve", detail: id } });
27	  revalidatePath("/admin/abuse");
28	  return { ok: true };
29	}
