57	/** Apply the standard mutation rate limits (short burst + hourly ceiling). */
58	function limitMutations(userId: string) {
59	  enforceRateLimit(`cal:mutate:burst:${userId}`, { max: 30, windowMs: 60 * 1000 });
60	  enforceRateLimit(`cal:mutate:${userId}`, { max: 600, windowMs: 60 * 60 * 1000 });
61	}
62	
63	/** True for a parseable ISO date-time string. */
64	function isValidISO(s: unknown): s is string {
65	  return typeof s === "string" && s.trim() !== "" && !Number.isNaN(Date.parse(s));
66	}
67	
68	/** Short, client-safe message from a thrown value. */
69	function cleanMsg(e: unknown): string {
70	  return String((e as Error)?.message ?? e ?? "Unknown error").slice(0, 300);
71	}
72	
73	/** Normalise a collection/object url for comparison (drop trailing slashes). */
74	function normUrl(u: string): string {
75	  return u.replace(/\/+$/, "");
76	}
77	
78	/** Does a calendar advertise support for the given component (VEVENT/VTODO)? */
79	function supportsComponent(cal: DAVCalendar, comp: string): boolean {
80	  const comps = cal.components;
81	  if (!comps || comps.length === 0) return true; // unknown — include it
82	  return comps.some((c) => c.toUpperCase() === comp);
83	}
84	
85	/** Human-friendly calendar name, falling back to the last url segment. */
86	function calName(cal: DAVCalendar): string {
87	  const dn = cal.displayName;
88	  if (typeof dn === "string" && dn.trim()) return dn.trim();
89	  const leaf = decodeURIComponent(normUrl(cal.url).split("/").pop() || "");
90	  return leaf || "Calendar";
91	}
92	
93	/** Map a tsdav DAVCalendar to the contract CalendarInfo. */
94	function toCalendarInfo(cal: DAVCalendar): CalendarInfo {
95	  return {
96	    id: cal.url,
97	    name: calName(cal),
98	    color: typeof cal.calendarColor === "string" ? cal.calendarColor : undefined,
99	    // SOGo does not surface a reliable per-collection read-only flag over the
100	    // default PROPFIND set; treat collections as writable and let the server
101	    // reject any unauthorised write.
102	    readOnly: false,
103	  };
104	}
