170	/** All events across the user's calendars overlapping [rangeStart, rangeEnd). */
171	export async function listEvents(
172	  rangeStartISO: string,
173	  rangeEndISO: string,
174	  mailboxAddress?: string,
175	): Promise<CalEvent[]> {
176	  if (!isValidISO(rangeStartISO) || !isValidISO(rangeEndISO)) {
177	    throw new Error("Invalid date range.");
178	  }
179	  const { cred } = await resolveMailbox(mailboxAddress);
180	  const client = await caldavClient(cred);
181	  const cals = (await fetchCalendars(client)).filter((c) => supportsComponent(c, "VEVENT"));
