192	/** Create a new event: PUT a fresh .ics object into the target calendar. */
193	export async function createEvent(
194	  input: EventInput,
195	  mailboxAddress?: string,
196	): Promise<{ ok: boolean; id?: string; error?: string }> {
197	  const { user, cred } = await resolveMailbox(mailboxAddress);
198	  limitMutations(user.id);
199	  const invalid = validateEventInput(input);
200	  if (invalid) return { ok: false, error: invalid };
201	
202	  try {
203	    const client = await caldavClient(cred);
204	    const calendar = await assertOwnedCalendar(client, input.calendarId);
205	    const uid = newUID();
206	    const ics = buildEventICS(input, uid);
207	    const id = await putObject(client, calendar.url, `${uid}.ics`, ics);
208	    return { ok: true, id };
209	  } catch (e) {
210	    return { ok: false, error: cleanMsg(e) };
211	  }
212	}
