46	const planSchema = z.object({
47	  id: z.string().optional(),
48	  gameFamily: z.enum(GAME_FAMILIES),
49	  name: z.string().min(2).max(80),
50	  ramMB: z.coerce.number().int().min(256).max(262144),
51	  cpuCores: z.coerce.number().int().min(1).max(64),
52	  diskGB: z.coerce.number().int().min(1).max(4096),
53	  slots: z.coerce.number().int().min(1).max(100000).optional(),
54	  priceCents: z.coerce.number().int().min(0).max(100000000),
55	  termMonths: z.coerce.number().int().min(1).max(36),
56	  basePlanId: z.string().min(1),
57	  osTemplateId: z.string().optional(),
58	  sortOrder: z.coerce.number().int().min(0).max(100000),
59	});
