61	/**
62	 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
63	 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
64	 * to the same game family, if provided).
65	 */
66	export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
67	  const admin = await requireArea("billing");
68	
69	  const rawSlots = String(formData.get("slots") ?? "").trim();
70	  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
71	  const parsed = planSchema.safeParse({
72	    id: formData.get("id") || undefined,
73	    gameFamily: formData.get("gameFamily"),
74	    name: formData.get("name"),
75	    ramMB: formData.get("ramMB"),
76	    cpuCores: formData.get("cpuCores"),
77	    diskGB: formData.get("diskGB"),
78	    slots: rawSlots === "" ? undefined : rawSlots,
79	    priceCents: formData.get("priceCents"),
80	    termMonths: formData.get("termMonths"),
81	    basePlanId: formData.get("basePlanId"),
82	    osTemplateId: rawOs === "" ? undefined : rawOs,
83	    sortOrder: formData.get("sortOrder") ?? 0,
84	  });
85	  if (!parsed.success) {
86	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
87	  }
88	  const d = parsed.data;
89	
90	  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
91	  if (!base) return { error: "Choose a valid base VPS plan for provisioning." };
92	
93	  let osTemplateId: string | null = null;
94	  if (d.osTemplateId) {
95	    const os = await db.osTemplate.findUnique({ where: { id: d.osTemplateId } });
96	    if (!os) return { error: "Selected game image not found." };
97	    if (os.family !== d.gameFamily) {
98	      return { error: `That image belongs to "${os.family}", not "${d.gameFamily}".` };
99	    }
100	    osTemplateId = os.id;
101	  }
102	
103	  const featured = formData.get("featured") === "on";
104	  const active = formData.get("active") === "on";
105	
106	  const data = {
107	    gameFamily: d.gameFamily,
108	    name: d.name.trim(),
109	    ramMB: d.ramMB,
110	    cpuCores: d.cpuCores,
111	    diskGB: d.diskGB,
112	    slots: d.slots ?? null,
113	    priceCents: d.priceCents,
114	    termMonths: d.termMonths,
115	    basePlanId: d.basePlanId,
116	    osTemplateId,
117	    featured,
118	    active,
119	    sortOrder: d.sortOrder,
120	  };
121	
122	  if (d.id) {
123	    const existing = await db.gamePlan.findUnique({ where: { id: d.id } });
124	    if (!existing) return { error: "Tier not found." };
125	    await db.gamePlan.update({ where: { id: d.id }, data });
126	  } else {
127	    await db.gamePlan.create({ data });
128	  }
129	
130	  await db.auditLog.create({
131	    data: {
132	      userId: admin.id,
133	      action: d.id ? "gameplan.update" : "gameplan.create",
134	      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
135	    },
136	  });
137	  revalidatePath("/admin/game-plans");
138	  return { ok: true };
139	}
