173	
174	/** Short random suffix so auto-generated hostnames don't collide. */
175	function rand(n = 6): string {
176	  return Math.random().toString(36).slice(2, 2 + n);
177	}
178	
179	/**
180	 * Order a game server from a GamePlan tier. Mirrors the VPS deploy path
181	 * (lib/actions.ts payAndDeploy -> lib/order.ts placeOrder):
182	 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
183	 * create the Server (sized by the tier's base VPS plan, running the game image)
184	 * plus a PROVISION Job in one transaction. Redirects to the new server.
185	 */
186	export async function orderGameServer(gamePlanId: string, termMonthsRaw?: number): Promise<Result> {
187	  // Spend path: this debits the wallet for the tier's flat price. The docblock
188	  // above says it mirrors the VPS deploy path — `payAndDeploy` (lib/actions.ts)
189	  // has carried this guard since it was written and this copy never picked it up.
190	  await assertNotImpersonating();
191	  const user = await requireUser();
192	  // Purchase gate: an unverified address means we cannot reach the person we
193	  // are about to charge. See lib/email-verification.ts.
194	  const unverified = await emailVerificationError(user);
195	  if (unverified) return { error: unverified };
196	
197	  // Feature flag: game servers can be switched off platform-wide.
198	  if (!(await getSettingBool("feature_game_servers", true))) {
199	    return { error: "Game servers aren't available right now." };
200	  }
201	
202	  // Game servers are Server rows too, so they count toward the per-user cap
203	  // (`max_servers_per_user`, default 10; 0 = unlimited).
204	  const cap = await getSettingInt("max_servers_per_user", 10);
205	  if (cap > 0) {
206	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
207	    if (owned >= cap) {
208	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
209	    }
210	  }
211	
212	  const gp = await db.gamePlan.findUnique({
213	    where: { id: gamePlanId },
214	    include: { basePlan: true },
215	  });
216	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
217	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
218	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
219	    return { error: "Unknown game family." };
220	  }
221	
222	  // Resolve the game image: the tier's own OsTemplate, else any active image for
223	  // this game family. A game server can't provision without an image.
224	  let osTemplateId = gp.osTemplateId;
225	  if (osTemplateId) {
226	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
227	    if (!os?.active) osTemplateId = null;
228	  }
229	  if (!osTemplateId) {
230	    const os = await db.osTemplate.findFirst({
231	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
232	      orderBy: { sortOrder: "asc" },
233	    });
234	    if (!os) return { error: "No game image is configured for this game yet." };
235	    osTemplateId = os.id;
236	  }
237	
238	  // Managed first-month-free. A game plan is a flat all-in term price, so the
239	  // credit is ONE month of that rate (firstMonthCreditCents); a single-month plan
240	  // lands at $0. `fullCharge` is the flat price. The credit applies ONLY if the
241	  // atomic claim inside the charge tx succeeds — otherwise (already redeemed by
242	  // this account/IP, or the promo is off) the server is created at FULL price. The
243	  // eligibility pre-check only picks the balance gate so a first-time customer with
244	  // just enough for the discounted price isn't wrongly turned away.
245	  // First-month-free is scoped to Shared Web Hosting only — game plans always
246	  // bill full. firstMonthFreeAppliesTo("GAME") is false, so promoEnabled is false.
247	  const promoEnabled = firstMonthFreeAppliesTo("GAME") && (await firstMonthFreeEnabled());
248	  const campaign = promoCampaignFromCookie(await cookies());
249	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
250	  // Billing term (Monthly / Annual). `gameMonthly` is the plan's per-month base
251	  // (every seeded plan is `termMonths: 1`, so it is just `priceCents`); the term is
252	  // priced through the SAME `termPriceCents` formula the renewal uses, with the
253	  // annual rate resolved once, frozen onto the Server and read back at renewal —
254	  // displayed === charged === renewed. For a monthly order this equals the old flat
255	  // `gp.priceCents`, so nothing changes for the monthly term.
256	  const term = normalizeProductTerm(termMonthsRaw);
257	  const annualPct = await annualDiscountPct();
258	  const gameMonthly = Math.round(gp.priceCents / Math.max(1, gp.termMonths));
259	  const fullCharge = termPriceCents(gameMonthly, term, annualPct);
260	  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
261	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
262	  const anticipated = eligible ? promoCharge : fullCharge;
263	  if (user.balanceCents < anticipated) {
264	    return { error: "Insufficient balance. Top up your wallet first." };
265	  }
266	
267	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
268	  // letting game servers commit host RAM past capacity. Check the base plan's
269	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
270	  const capacity = await capacityCheck(gp.basePlanId);
271	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
272	
273	  const hostname = `${gp.gameFamily}-${rand()}`;
274	
275	  let server;
276	  try {
277	    server = await db.$transaction(async (tx) => {
278	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
279	      let debitCents = fullCharge;
280	      let promoClaimId: string | null = null;
281	      if (promoEnabled) {
282	        const claim = await claimFirstMonthFree(tx, {
283	          userId: user.id,
284	          ipHash,
285	          serviceType: "GAME",
286	          campaign,
287	          chargedCents: promoCharge,
288	        });
289	        if (claim.claimed) {
290	          debitCents = promoCharge;
291	          promoClaimId = claim.id;
292	        }
293	      }
294	      const note = debitCents < fullCharge ? " — First month free" : "";
295	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
296	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
297	      await debitWallet(tx, user.id, debitCents);
298	      await tx.walletTransaction.create({
299	        data: {
300	          userId: user.id,
301	          amountCents: -debitCents,
302	          description: `Game server: ${gp.name} (${gp.gameFamily}) — ${termLabel}${note}`,
303	        },
304	      });
305	      const s = await tx.server.create({
306	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
307	        // on Server until regenerated at deploy (see lib/order.ts's Server create).
308	        data: {
309	          name: hostname,
310	          hostname,
311	          userId: user.id,
312	          planId: gp.basePlanId,
313	          gamePlanId: gp.id,
314	          osTemplateId: osTemplateId!,
315	          // The customer's chosen term rides the Server row now (Monthly / Annual);
316	          // renewalCharge's game branch renews `gameMonthly × termMonths × (1 − annual)`.
317	          termMonths: term,
318	          // A game plan carries no seasonal promo, so this term was sold at 0% off —
319	          // proration (if ever wired for game) must price against full price.
320	          termPromoPercent: 0,
321	          // The annual rate frozen at sale, so the renewal bills the SAME price the
322	          // order charged even if the admin retunes `annual_discount_percent` later.
323	          annualDiscountPct: annualPct,
324	          wantsDedicatedIp: false,
325	          expiresAt: addMonths(new Date(), term),
326	        } as Prisma.ServerUncheckedCreateInput,
327	      });
328	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
329	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
330	      return s;
331	    });
332	  } catch (e) {
333	    if (e instanceof InsufficientBalanceError) {
334	      return { error: "Insufficient balance. Top up your wallet first." };
335	    }
336	    throw e;
337	  }
338	
339	  await db.auditLog.create({
340	    data: {
341	      userId: user.id,
342	      action: "gameserver.order",
343	      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
344	    },
345	  });
346	  redirect(`/dashboard/servers/${server.id}`);
